CREATE OR REPLACE PROCEDURE sp(arg1 integer, arg2 text, arg3 text, arg4 integer, arg5 text, arg6 integer)
LANGUAGE plpgsql
AS $$
DECLARE
    v_threshold integer := arg1;
    v_status    text    := arg2;
    v_op        text    := arg3;
    v_handled   integer := 0;
    v_batch     integer := 10;
    v_state     text    := 'INIT';
    v_high      boolean := false;
    r           RECORD;
    v_priority  text;
BEGIN
    IF arg1 < 3 THEN
        v_state := 'MINIMAL_PROCESS';
        FOR r IN SELECT "ResID", "ResName", "Address"
                 FROM "Restaurant"
                 WHERE "ResID" < arg1
                   AND "ResName" LIKE arg2
        LOOP
            v_handled := v_handled + 1;
            IF r."ResID" > 25 THEN
                UPDATE "Restaurant"
                SET "ResName" = 'PROMOTED'
                WHERE "ResID" = r."ResID";
            ELSIF r."Address" = v_op THEN
                DELETE FROM "Visits_Restaurant"
                WHERE "ResID" = r."ResID";
                DELETE FROM "Type_Of_Restaurant"
                WHERE "ResID" = r."ResID";
                DELETE FROM "Restaurant"
                WHERE "ResID" = r."ResID"
                  AND "ResName" = r."ResName";
            ELSE
                UPDATE "Restaurant"
                SET "Address" = 'PENDING'
                WHERE "ResID" = r."ResID";
            END IF;
            IF v_handled >= v_batch THEN
                v_batch := v_batch + 5;
            END IF;
        END LOOP;

    ELSIF arg1 < 8 THEN
        v_state := 'STANDARD_PROCESS';
        FOR r IN SELECT "StuID", "LName", "city_code"
                 FROM "Student"
                 WHERE "StuID" BETWEEN arg4 - 5 AND arg4 + 15
        LOOP
            v_handled := v_handled + 1;
            IF r."city_code" = v_op THEN
                UPDATE "Student"
                SET "Sex" = 'U'
                WHERE "city_code" = r."city_code";
            END IF;
            IF r."LName" = arg5 THEN
                UPDATE "Student"
                SET "city_code" = 'MATCHED'
                WHERE "LName" = r."LName";
            END IF;
            IF r."LName" LIKE 'ACTIVE%' THEN
                UPDATE "Student"
                SET "LName" = 'PROCESSED'
                WHERE "LName" = r."LName";
            ELSIF r."StuID" > arg4 + 5 THEN
                v_threshold := v_threshold + r."StuID";
            ELSE
                DELETE FROM "Student"
                WHERE "StuID" = r."StuID"
                  AND "LName" = 'EXPIRED';
            END IF;
            IF v_handled >= v_batch THEN
                v_batch := v_batch + 5;
            END IF;
        END LOOP;

    ELSIF arg1 < 18 THEN
        v_state := 'ENHANCED_PROCESS';
        FOR r IN SELECT "ResTypeID"
                 FROM "Restaurant_Type"
                 WHERE "ResTypeID" > arg6 - 20
        LOOP
            v_handled := v_handled + 1;
            IF r."ResTypeID" < 50 THEN
                v_priority := 'LOW_PRIORITY';
            ELSIF r."ResTypeID" < 150 THEN
                v_priority := 'MEDIUM_PRIORITY';
            ELSE
                v_priority := 'HIGH_PRIORITY';
                v_high := true;
            END IF;
            v_status := v_priority;
            UPDATE "Restaurant_Type"
            SET "ResTypeID" = "ResTypeID" + 10
            WHERE "ResTypeID" = r."ResTypeID";
            IF v_handled >= v_batch THEN
                v_batch := v_batch + 5;
            END IF;
        END LOOP;

    ELSIF arg1 < 25 THEN
        v_state := 'ARCHIVE_MODE';
        UPDATE "Restaurant"
        SET "Address" = 'ARCHIVED'
        WHERE "ResID" < arg1
          AND "ResName" <> v_status;

    ELSIF arg1 < 40 THEN
        v_state := 'CLEANUP_MODE';
        DELETE FROM "Student"
        WHERE "StuID" < arg4
          AND "LName" = 'OBSOLETE';

    ELSE
        v_state := 'BOOST_MODE';
        UPDATE "Restaurant_Type"
        SET "ResTypeID" = arg6 + 100
        WHERE "ResTypeID" > 200;
    END IF;

    IF v_status = 'HIGH_PRIORITY' OR v_high THEN
        UPDATE "Restaurant_Type"
        SET "ResTypeID" = "ResTypeID" * 2
        WHERE "ResTypeID" > 100;
    ELSIF v_state = 'ARCHIVE_MODE' THEN
        DELETE FROM "Restaurant"
        WHERE "Address" = 'ARCHIVED'
          AND "ResID" < v_threshold - 10;
